"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[19922],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>l});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},50854:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>a,contentTitle:()=>l,default:()=>k,frontMatter:()=>o,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/04/09","title":"2023-04-09","description":"Jeg skulle \xf8nske GPT4 aldri hadde funnet sted.","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/09.md","sourceDirName":"2023/04","slug":"/2023/04/09","permalink":"/nb/2023/04/09","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/09.md","tags":[],"version":"current","frontMatter":{"localized_date":"9. april 2023","top_news":"Jeg skulle \xf8nske GPT4 aldri hadde funnet sted."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-10","permalink":"/nb/2023/04/10"},"next":{"title":"2023-04-08","permalink":"/nb/2023/04/08"}}');var i=n(23420),s=n(3331);const o={localized_date:"9. april 2023",top_news:"Jeg skulle \xf8nske GPT4 aldri hadde funnet sted."},l="2023-04-09",a={},d=[{value:"Jeg skulle \xf8nske GPT4 aldri hadde funnet sted.",id:"jeg-skulle-\xf8nske-gpt4-aldri-hadde-funnet-sted",level:2},{value:"Hvorfor menneskelige samfunn har utviklet seg s\xe5 lite i l\xf8pet av 300 000 \xe5r.",id:"hvorfor-menneskelige-samfunn-har-utviklet-seg-s\xe5-lite-i-l\xf8pet-av-300-000-\xe5r",level:2},{value:"The Garbage Collection Handbook, 2. utgave.",id:"the-garbage-collection-handbook-2-utgave",level:2},{value:"Ten\xe5ringer i New Orleans fant et nytt bevis p\xe5 Pytagoras&#39; l\xe6resetning.",id:"ten\xe5ringer-i-new-orleans-fant-et-nytt-bevis-p\xe5-pytagoras-l\xe6resetning",level:2},{value:"Avsier dommere strengere dommer n\xe5r de er sultne? En studie for god til \xe5 v\xe6re sann",id:"avsier-dommere-strengere-dommer-n\xe5r-de-er-sultne-en-studie-for-god-til-\xe5-v\xe6re-sann",level:2},{value:"Alt som reklameres for p\xe5 sosiale medier er overpriset s\xf8ppel",id:"alt-som-reklameres-for-p\xe5-sosiale-medier-er-overpriset-s\xf8ppel",level:2},{value:"Go port av SQLite uten CGo.",id:"go-port-av-sqlite-uten-cgo",level:2},{value:"Hvorfor og hvordan vi pensjonerte Elm p\xe5 Culture Amp",id:"hvorfor-og-hvordan-vi-pensjonerte-elm-p\xe5-culture-amp",level:2},{value:"FAA K-12 flyplassdesignutfordring i Minecraft",id:"faa-k-12-flyplassdesignutfordring-i-minecraft",level:2},{value:"Google vil forby finansielle utl\xe5nsapper \xe5 f\xe5 tilgang til brukernes bilder og kontakter.",id:"google-vil-forby-finansielle-utl\xe5nsapper-\xe5-f\xe5-tilgang-til-brukernes-bilder-og-kontakter",level:2},{value:"Go 1.21 vil (sannsynligvis) ha en statisk verkt\xf8ykjede p\xe5 Linux.",id:"go-121-vil-sannsynligvis-ha-en-statisk-verkt\xf8ykjede-p\xe5-linux",level:2},{value:"Elektrisitetspriser etter land",id:"elektrisitetspriser-etter-land",level:2},{value:"0x0: Del filer fra terminalen",id:"0x0-del-filer-fra-terminalen",level:2},{value:"Iran installerer kameraer p\xe5 offentlige steder for \xe5 identifisere og straffe utilsl\xf8rte kvinner.",id:"iran-installerer-kameraer-p\xe5-offentlige-steder-for-\xe5-identifisere-og-straffe-utilsl\xf8rte-kvinner",level:2},{value:"En streng p\xe5 1,5 GB",id:"en-streng-p\xe5-15-gb",level:2},{value:"Paul Graham er investor i selskapet som pr\xf8ver \xe5 drepe Twitter.",id:"paul-graham-er-investor-i-selskapet-som-pr\xf8ver-\xe5-drepe-twitter",level:2},{value:"FCC advarer Portland kirke om \xe5 stenge pirat FM som opererer under kirket\xe5rnet.",id:"fcc-advarer-portland-kirke-om-\xe5-stenge-pirat-fm-som-opererer-under-kirket\xe5rnet",level:2},{value:"GNU+Linux b\xe6rbare datamaskiner med forh\xe5ndsinstallert Libreboot, basert p\xe5 coreboot.",id:"gnulinux-b\xe6rbare-datamaskiner-med-forh\xe5ndsinstallert-libreboot-basert-p\xe5-coreboot",level:2},{value:"P\xe5 jakt etter regnbuer: Design for fargeblindhet",id:"p\xe5-jakt-etter-regnbuer-design-for-fargeblindhet",level:2},{value:"For \xe5 \xf8ke l\xe6ringen, se \xe5 spille",id:"for-\xe5-\xf8ke-l\xe6ringen-se-\xe5-spille",level:2},{value:"Vis BrowserBox - gj\xf8r ting med nettlesere som du vanligvis ikke kan gj\xf8re",id:"vis-browserbox---gj\xf8r-ting-med-nettlesere-som-du-vanligvis-ikke-kan-gj\xf8re",level:2},{value:"Pydantic V2 omskrevet i Rust er 5-50 ganger raskere enn Pydantic V1.",id:"pydantic-v2-omskrevet-i-rust-er-5-50-ganger-raskere-enn-pydantic-v1",level:2},{value:"AI-drevne sanntidsv\xe6skesimuleringer er her.",id:"ai-drevne-sanntidsv\xe6skesimuleringer-er-her",level:2},{value:"Egendefinerte allokatorer i Rust",id:"egendefinerte-allokatorer-i-rust",level:2},{value:"The Erosion of Free Will: Hvorfor samfunnets tap av tro p\xe5 frihet er farlig",id:"the-erosion-of-free-will-hvorfor-samfunnets-tap-av-tro-p\xe5-frihet-er-farlig",level:2},{value:"Vis L\xe6r Rust 101 - En guide for \xe5 hjelpe deg med \xe5 bli en Rustacean",id:"vis-l\xe6r-rust-101---en-guide-for-\xe5-hjelpe-deg-med-\xe5-bli-en-rustacean",level:2},{value:"Trashcan - nettbasert tjeneste for indeksering av vitenskapelige artikler eller andre dokumenter.",id:"trashcan---nettbasert-tjeneste-for-indeksering-av-vitenskapelige-artikler-eller-andre-dokumenter",level:2},{value:"Vis Spotify-str\xf8mming av GDPR-dump lokal analysator",id:"vis-spotify-str\xf8mming-av-gdpr-dump-lokal-analysator",level:2},{value:"Hacking Google ReCAPTCHA v3 ved hjelp av forsterkende l\xe6ring (2019)",id:"hacking-google-recaptcha-v3-ved-hjelp-av-forsterkende-l\xe6ring-2019",level:2},{value:"Eks-brannsjef med brudd i hodeskallen etter angrep med metallr\xf8r.",id:"eks-brannsjef-med-brudd-i-hodeskallen-etter-angrep-med-metallr\xf8r",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-09",children:"2023-04-09"})}),"\n",(0,i.jsx)(r.h2,{id:"jeg-skulle-\xf8nske-gpt4-aldri-hadde-funnet-sted",children:"Jeg skulle \xf8nske GPT4 aldri hadde funnet sted."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://chaudhry.notion.site/I-wish-GPT4-had-never-happened-9f0cbf2848a44ec9911c07fb34ff5de3",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492730",children:"Discussion Service"}),".\nEn artikkel om den negative virkningen av GPT-4 f\xe5r oppmerksomhet med en blanding av meninger om beskatning, produktivitet, sosio\xf8konomiske klasser og offentlig regulering. Det skjer et massivt faglig skifte som for\xe5rsaker sosial uro, men noen hevder at det \xe5pner muligheter for tekniske ferdigheter. Rikdomsfordeling og eierskap i et fritt samfunn debatteres, og noen argumenterer for en ny l\xf8sning p\xe5 ulempene ved bruk av kunstig intelligens. ChatGPT hjelper brukerne til \xe5 f\xf8le seg tryggere p\xe5 programmeringsspr\xe5k, men det uttrykkes bekymring for den \xf8kte sannsynligheten for feil i AI-genererte koder. GPT-4 anses som et kraftig produktivitetsverkt\xf8y med potensial til \xe5 erstatte utviklere p\xe5 visse omr\xe5der. AIs innvirkning p\xe5 samfunnet og arbeidsstyrken er enn\xe5 ikke klar, men AI er ikke ment \xe5 erstatte menneskelige ferdigheter og d\xf8mmekraft."]}),"\n",(0,i.jsx)(r.h2,{id:"hvorfor-menneskelige-samfunn-har-utviklet-seg-s\xe5-lite-i-l\xf8pet-av-300-000-\xe5r",children:"Hvorfor menneskelige samfunn har utviklet seg s\xe5 lite i l\xf8pet av 300 000 \xe5r."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://woodfromeden.substack.com/p/violent-enough-to-stand-still",children:"Original"}),".\nArtikkelen diskuterer antropologen Napoleon Chagnons funn om Yanomam\xf6-krigf\xf8ring og deres unike kulturelle praksis som holdt befolkningen nede samtidig som de hadde rikelig med ressurser. Artikkelen kaster lys over pre-malthusianske samfunn og hvordan mennesker har eksistert i en tilstand av befolkningsmessig likevekt. Menneskelig utvikling er episodisk, og sp\xf8rsm\xe5let er hva som fikk menn til \xe5 forlate nullsumspillet og utvikle mer komplekse samfunn. Artikkelen foresl\xe5r et nytt perspektiv p\xe5 menneskets historie og sivilisasjonens utvikling, og kommentarene bringer inn ulike perspektiver, inkludert marxistiske synspunkter p\xe5 krig i primitive samfunn."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492591",children:"Discussion Service"}),".\nDiskusjon om hvorfor menneskelige samfunn stagnerte i 300 000 \xe5r, med ulike perspektiver p\xe5 teknologiens rolle, befolkningsvekst og lese- og skriveferdigheter. Noen brukere peker p\xe5 betydningen av spesifikk kunnskap p\xe5 omr\xe5der som ingeni\xf8rfag og matematikk. En samtale om samfunnsutvikling utfordrer forfatterens premiss og fremhever behovet for \xe5 ta hensyn til samfunnsmessige og kulturelle faktorer utover materiell teknologi. Tech Times-rapporten tar sikte p\xe5 \xe5 gi kortfattet, upartisk innsikt for eksperter p\xe5 omr\xe5det. Hold deg n\xf8ytral og fokuser p\xe5 n\xf8kkelpunkter som interesserer leserne, og unng\xe5 politiske eller religi\xf8se uttalelser."]}),"\n",(0,i.jsx)(r.h2,{id:"the-garbage-collection-handbook-2-utgave",children:"The Garbage Collection Handbook, 2. utgave."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.routledge.com/The-Garbage-Collection-Handbook-The-Art-of-Automatic-Memory-Management/Jones-Hosking-Moss/p/book/9781032218038",children:"Original"}),".\nThe Garbage Collection Handbook, 2nd Edition oppdaterer tilstanden for forskning og utvikling av automatisk minneh\xe5ndtering, med fokus p\xe5 de nyeste avanserte teknikkene, som parallell, inkrementell, samtidig og sanntids s\xf8ppelsamling, og deres implikasjoner for designere og implementat\xf8rer av s\xf8ppelsamlere. Teksten tar ogs\xe5 for seg nye utfordringer som f\xf8lge av nylige fremskritt innen maskinvare og programvare. Denne omfattende veiledningen er f\xf8rst og fremst ment for forskere og utviklere innen minneh\xe5ndtering som s\xf8ker innsikt i ulike minneh\xe5ndteringsalgoritmer og design."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492307",children:"Discussion Service"}),".\n'The Garbage Collection Handbook, 2nd Edition' utgitt, med informasjon om Concurrent copying/compaction GC og h\xe5ndtering av sidefeil. Userfaultfd og line\xe6r logikk nevnt. Debatt om GC i Java/Ada, sporing av GC og referansetellingskonnektorer. Viktigheten av \xe5 minimere heap-minneallokering diskutert. Det finnes sanntids- og ikke-sanntids GC-er. Noen brukere mener GC er viktig, mens andre foretrekker manuell minneh\xe5ndtering. Ekspertise innen spr\xe5kdesign \u2260 ekspertise innen informatikk. Diskusjon om verdityper i Swift og sarkasme om garbage collection book i Rust."]}),"\n",(0,i.jsx)(r.h2,{id:"ten\xe5ringer-i-new-orleans-fant-et-nytt-bevis-p\xe5-pytagoras-l\xe6resetning",children:"Ten\xe5ringer i New Orleans fant et nytt bevis p\xe5 Pytagoras' l\xe6resetning."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://keith-mcnulty.medium.com/heres-how-two-new-orleans-teenagers-found-a-new-proof-of-the-pythagorean-theorem-b4f6e7e9ea2d",children:"Original"}),".\nTo ten\xe5ringsjenter har presentert et nytt bevis p\xe5 Pythagoras' l\xe6resetning for American Mathematical Society, noe som skapte stor oppstandelse. Dette eksemplariske eksemplet viser hvor \xe5pen element\xe6r matematikk er for alle, og kan oppmuntre andre til \xe5 utforske matematikk."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35497696",children:"Discussion Service"}),".\nTen\xe5ringer i New Orleans oppdaget et nytt bevis for Pythagoras' l\xe6resetning basert p\xe5 sinusloven. Eksperter deler ulike meninger. De to kvinnelige afroamerikanske studentene presenterte arbeidet sitt for American Mathematical Society. Beviset bruker uendelige serier av nestede trekanter og trigonometriske konvensjoner. Noen brukere foresl\xe5r alternative m\xe5ter \xe5 bevise teoremet p\xe5. Underrepresenterte gruppers prestasjoner og foreldrenes engasjement diskuteres. Beviset trenger bare \xe5 v\xe6re logisk korrekt. Videreg\xe5ende elevers prestasjoner granskes n\xf8ye av erfarne matematikere. Beviset er ikke nytt, men det enkleste og vakreste trigonometriske beviset hittil. Viktigheten av kreativitet og originalitet fremhevet. YC Summer 2023-s\xf8knadene er \xe5pne."]}),"\n",(0,i.jsx)(r.h2,{id:"avsier-dommere-strengere-dommer-n\xe5r-de-er-sultne-en-studie-for-god-til-\xe5-v\xe6re-sann",children:"Avsier dommere strengere dommer n\xe5r de er sultne? En studie for god til \xe5 v\xe6re sann"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://inews.co.uk/news/do-judges-give-out-tougher-sentences-when-hungry-the-story-behind-a-study-too-good-to-be-true-2238347",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35491060",children:"Discussion Service"}),".\nEn studie som antyder at dommere gir strengere dommer n\xe5r de er sultne, bestrides med henvisning til erfaringer med faste. Religi\xf8s faste kan faktisk v\xe6re til fordel for dommeres d\xf8mmekraft, mens korte ramadan-faster ikke kan sammenlignes med lengre faste. Fasteerfaringer og meninger varierer, og noen bemerker klarhet og produktivitet. Studier viser positive sammenhenger mellom kognitiv ytelse og faste eller begrenset karbohydratdiett, men det er behov for mer forskning. Dommere som fastet under ramadan i Pakistan var mer tilb\xf8yelige til \xe5 frikjenne tiltalte med 10 % for hver ekstra time de fastet, men utvalgsst\xf8rrelsen var liten og planleggingsskjevheter ble notert. Vitenskapelige studier av sosiale fenomener er up\xe5litelige og \xe5pne for ulike tolkninger basert p\xe5 kommentarer. Vitenskapens natur og betydningen av delt sannhet i vitenskapelig diskurs ble ogs\xe5 diskutert."]}),"\n",(0,i.jsx)(r.h2,{id:"alt-som-reklameres-for-p\xe5-sosiale-medier-er-overpriset-s\xf8ppel",children:"Alt som reklameres for p\xe5 sosiale medier er overpriset s\xf8ppel"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://pluralistic.net/2023/04/08/late-stage-sea-monkeys/#jeremys-razors",children:"Original"}),".\nEn studie fra Carnegie Mellon og Pamplin College fant at m\xe5lrettede annonser p\xe5 sosiale medier i gjennomsnitt koster 10 % mer og kommer fra leverand\xf8rer med d\xe5rlige rangeringer, noe som f\xe5r studien til \xe5 konkludere med at alle annonserte produkter p\xe5 sosiale medier er overpriset s\xf8ppel. Kontekstuelle annonser fungerer like bra og har bedre kontroll over kreativt innhold. Det er behov for lovgivningsmessige tiltak for \xe5 innf\xf8re retningslinjer for samtykke til datainnsamling og for \xe5 regulere annonseteknologimarkedet. En f\xf8deral personvernlov kan forhindre spionasje fra sosiale mediegiganter og fremme konkurranse i appbutikkene, slik at mediene kan tjene mer penger. \xc5 flytte kontrollen fra Big Tech kan v\xe6re til fordel for mediene generelt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492672",children:"Discussion Service"}),".\nI en artikkel hevdes det at annonser i sosiale medier selger overpriset s\xf8ppel, noe som im\xf8teg\xe5s av synspunkter om fordelene, blant annet at sm\xe5 bedrifter kan annonsere for mindre penger. Artikkelen fokuserer p\xe5 barberh\xf8velmarkedet og nisjeprodukter. Det fremmes forslag om produkter av h\xf8y kvalitet, merkevareforskning og regulering av reklame. Begrensningene ved produktreklame og anmeldelser diskuteres, og nedgangen i produktkvalitet er et vanlig tema. Noen p\xe5peker at nyere vekstfokuserte merker kan tilby bedre tilbud. Det oppleves problemer med m\xe5lrettet reklame, produkter med m\xe5netopografi og svindel."]}),"\n",(0,i.jsx)(r.h2,{id:"go-port-av-sqlite-uten-cgo",children:"Go port av SQLite uten CGo."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://gitlab.com/cznic/sqlite",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35488980",children:"Discussion Service"}),".\nEn Go-port av SQLite uten CGo for krysskompilering diskuteres p\xe5 Discussion Service, med forslag til alternativer. Bekymringer om stabilitet og transaksjonsatferd er reist, og noen anbefaler C-biblioteket. Det er debatt om implementering av SQLite i Go, og fordelene med Go-sqlite fremfor standard drivere. Den st\xf8rste fordelen med Go-sqlite er ikke \xe5 bruke CGO, med utviklede metoder som bruker C to Go-kompilator for SQLite. Noen roser metoden, mens andre rapporterer om transaksjonsl\xe5sfeil. En alternativ tiln\xe6rming ved bruk av Wasm anbefales."]}),"\n",(0,i.jsx)(r.h2,{id:"hvorfor-og-hvordan-vi-pensjonerte-elm-p\xe5-culture-amp",children:"Hvorfor og hvordan vi pensjonerte Elm p\xe5 Culture Amp"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://kevinyank.com/posts/on-endings-why-how-we-retired-elm-at-culture-amp/",children:"Original"}),'.\nCulture Amp har pensjonert Elm som sitt foretrukne spr\xe5k for ny frontend-kode etter fire \xe5r til tross for at det tidligere ble anbefalt av selskapets tekniske leder. Flyttingen skyldtes et fors\xf8k fra Culture Amps designteam p\xe5 \xe5 bygge et spr\xe5kagnostisk bibliotek med gjenbrukbare brukergrensesnittkomponenter med Web Components, som krever sitt eget rammeverk. Culture Amp valgte \xe5 holde seg til React p\xe5 grunn av oppkj\xf8pet av et selskap med en fullstendig React-kodebase og TypeScripts evne til \xe5 matche Elms tilstandsstyring. Culture Amps beslutning gjenspeiler en \xf8kende trend mot \xe5 velge React i TypeScript for nye prosjekter, og Elm kan g\xe5 fra "adopt" til "contain" -status p\xe5 deres Tech Radar. Ingeni\xf8rer st\xf8ttet beslutningen om \xe5 inneholde Elm p\xe5 grunn av kompleksiteten det skaper.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35495910",children:"Discussion Service"}),".\nCulture Amps beslutning om \xe5 avvise jobbs\xf8kere med en bestemt spr\xe5kpreferanse utl\xf8ser diskusjoner p\xe5 Discussion Service, der noen er enige og andre uenige. Noen brukere advarer mot \xe5 v\xe6re for ivrige n\xe5r det gjelder en teknologi og oppfordrer til \xe5 fokusere p\xe5 faktiske indikatorer p\xe5 kompetanse. Elms utfordringer og tilbakegang diskuteres, med forslag til andre spr\xe5k. Discussion Service-kommentarer diskuterer bedriftskultur, design av systemer og valg av teknologi. En tidligere Elm-bruker deler sine erfaringer med \xe5 bytte til TypeScript, mens et selskap med problemer med \xe5 vedlikeholde to rammeverk bestemmer seg for \xe5 fase ut Elm. Redakt\xf8ren m\xe5 unng\xe5 politiske eller religi\xf8se uttalelser og fange opp viktige punkter av interesse for teknologikyndige lesere."]}),"\n",(0,i.jsx)(r.h2,{id:"faa-k-12-flyplassdesignutfordring-i-minecraft",children:"FAA K-12 flyplassdesignutfordring i Minecraft"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.faa.gov/airport-design-challenge",children:"Original"}),".\nFAA Science, Technology, Engineering, and Math Aviation and Space Education (STEM AVSED) Program organiserer en Airport Design Challenge i Minecraft for elever i trinn K-12. Denne interaktive l\xe6rings- og samarbeidsmuligheten dekker emner som spenner fra flyplassutforming, fortau, belysning og strukturer til innovativ vekst. Deltakerne f\xe5r muligheten til \xe5 samarbeide med FAAs luftfarts- og ingeni\xf8reksperter, m\xf8te fagfolk innen luftfart og samarbeide med andre designere. Samarbeid mellom elever, foreldre og l\xe6rere utf\xf8res i et virtuelt milj\xf8, og kunnskapskontrolloppgaver og skjermbilder av design brukes for \xe5 gi tilbakemelding."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35494382",children:"Discussion Service"}),".\nFAA er vertskap for en flyplassdesignutfordring ved hjelp av Minecraft for K-12-elever i USA. Brukerne diskuterer de potensielle fordelene og begrensningene ved Minecraft som et pedagogisk og kreativt verkt\xf8y. Noen uttrykker bekymring over barns teknologibruk, mens andre fremhever potensialet for \xe5 dyrke senere interesser. Konkurransen vekker interesse som en unik kombinasjon av Minecraft og luftfartsdesign. Innlegget antyder at selv flyplassdesignere kan l\xe6re av kreativiteten til 12 \xe5r gamle barn. Konkurransen legger ogs\xe5 til rette for crowdsourcing av 3D-kopier av infrastrukturprosjekter og vekker interesse for offentlige infrastrukturprosjekter med \xe5pen kildekode. Discussion Service-brukere uttrykker positive reaksjoner p\xe5 Minecraft-inspirerte prosjekter som stimulerer barns vekst og l\xe6ring, for eksempel programmering og tekniske ferdigheter."]}),"\n",(0,i.jsx)(r.h2,{id:"google-vil-forby-finansielle-utl\xe5nsapper-\xe5-f\xe5-tilgang-til-brukernes-bilder-og-kontakter",children:"Google vil forby finansielle utl\xe5nsapper \xe5 f\xe5 tilgang til brukernes bilder og kontakter."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.pcmag.com/news/google-to-ban-financial-lending-apps-from-accessing-user-photos-contacts",children:"Original"}),".\nGoogle har oppdatert sine retningslinjer for personlige l\xe5n for \xe5 forhindre at apper som tilbyr l\xe5n f\xe5r tilgang til brukerkontakter eller bilder. Dette tiltaket tar sikte p\xe5 \xe5 bekjempe rovgrisk oppf\xf8rsel fra enkelte l\xe5ngivere som trakasserer og skremmer l\xe5ntakere til \xe5 betale utest\xe5ende gjeld. I tillegg til dette vil det kreves landsspesifikk lisensdokumentasjon for \xe5 bevise deres evne til \xe5 gi eller legge til rette for personlige l\xe5n, for eksempel i Pakistan. Slik praksis har f\xf8rt til at gjeldsinnkrevere har sendt manipulerte bilder til venner og familie av skyldnere, noe som har f\xf8rt til at en rekke m\xe5lrettede personer har tatt livet sitt i land som India og Kenya."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35494366",children:"Discussion Service"}),".\nGoogle vil forby utl\xe5nsapper \xe5 f\xe5 tilgang til brukernes bilder og kontakter. Forslagene omfatter en todelt tiln\xe6rming i Play-butikken eller presentasjon av falske data n\xe5r tillatelser nektes. Sikker kjernearkitektur lover \xe5 eliminere skadelig programvare. Brukere klager over for mange tillatelser og misbruk av data fra l\xe5neapper. Det etterlyses bedre regelverk eller en hviteliste for tilgang til l\xe5neapper. Bekymringer for personvernet og behov for individuell deling av kontakter. Behov for str\xf8mlinjeformet medietilgangsfunksjon. PC-brukere mangler tillatelsesgrenser. Alternative app-butikker kan svekke brukerbeskyttelsen. Unik svindel i Kenya. Google forbyr annonser for l\xf8nningsl\xe5n til tross for at de er tillatt i appbutikken."]}),"\n",(0,i.jsx)(r.h2,{id:"go-121-vil-sannsynligvis-ha-en-statisk-verkt\xf8ykjede-p\xe5-linux",children:"Go 1.21 vil (sannsynligvis) ha en statisk verkt\xf8ykjede p\xe5 Linux."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://utcc.utoronto.ca/~cks/space/blog/programming/Go121LinuxStaticToolchain",children:"Original"}),".\nDen kommende versjonen av Go 1.21 vil ha en statisk verkt\xf8ykjede p\xe5 Linux, noe som betyr at kompilatoren bare vil bli bygget ved hjelp av den rene Go-resolveren og vil v\xe6re en statisk kj\xf8rbar, med mindre utviklerne av en eller annen grunn g\xe5r tilbake. Dette vil gi en fin forbedring av livskvaliteten for folk som for det meste jobber p\xe5 nyere Linuxer, men som av og til m\xe5 forholde seg til eldre. Denne endringen vil imidlertid ikke automatisk gj\xf8re brukerprogrammene versjonsuavhengige. Forel\xf8pig har elementer av planen allerede landet i Go-utviklingsversjonen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35490941",children:"Discussion Service"}),".\nGo 1.21 for \xe5 ha raskere statisk verkt\xf8ykjede p\xe5 Linux, men kritikken om h\xe5ndtering av null peker panikk vedvarer fortsatt. Noen foresl\xe5r \xe5 ettermontere funksjoner uten \xe5 bryte bakoverkompatibiliteten, men andre argumenterer mot generikk. Brukere roser brukervennligheten og verkt\xf8ykjeden til Go. Rusts l\xe5nekontroll, minnebegrensninger og levetid diskuteres ogs\xe5. Go's DNS-resolver og avhengighet av libc diskuteres, med fordeler og ulemper med dynamisk vs. statisk kobling. Implementering av DNS-oppslag p\xe5 macOS diskutert, bygging av klientkj\xf8rbare filer i debian squeeze docker-container foresl\xe5tt, og bruk av Go for fullt reproduserbar verkt\xf8ykjede p\xe5 1.21."]}),"\n",(0,i.jsx)(r.h2,{id:"elektrisitetspriser-etter-land",children:"Elektrisitetspriser etter land"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.electricrate.com/data-center/electricity-prices-by-country/",children:"Original"}),".\nArtikkelen tar for seg kostnadene og kildene til elektrisitet p\xe5 tvers av land, og avsl\xf8rer hvordan Tyskland og Bermuda er de dyreste, mens Sudan, Venezuela og Iran er de billigste. De fleste land er fortsatt hovedsakelig avhengige av fossilt brensel for elektrisitetsproduksjon. USA har det h\xf8yeste str\xf8mforbruket i husholdningene, men en kostnad som tilsvarer det globale gjennomsnittet. Videre er 13 % av verdens befolkning fortsatt uten tilgang til elektrisitet. Det er viktig \xe5 ta hensyn til tilgang og b\xe6rekraft n\xe5r man analyserer str\xf8mpriser, ettersom lave priser ofte er skadelig for milj\xf8et."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35495579",children:"Discussion Service"}),'.\nEn artikkel om "Electricity Prices by Country" f\xe5r oppmerksomhet p\xe5 Hacker News, ettersom leserne diskuterer faktorer som regionale forskjeller i energibruk og propanbruk i landlige omr\xe5der. Brukere deler sine erfaringer med \xe5 redusere energiforbruket drastisk, mens andre p\xe5peker mangler i dataene og uttrykker overraskelse over lavt energiforbruk. Regionale prisvariasjoner p\xe5 grunn av geografi og politisk politikk er betydelige, og prisene b\xf8r normaliseres etter lokal gjennomsnittsinntekt for en rettferdig sammenligning. Argentinske og venezuelanske subsidier vekker bekymring, mens kritikere antyder forenklede datasammenligninger for markedsf\xf8ringsform\xe5l. Tysklands h\xf8ye priser tilskrives kostnadene for naturgass, mens prisene i Sverige og Storbritannia ikke samsvarer med kostnadene p\xe5 stedet. Artikkelen dekker elektrisitetspriser i afrikanske land, selv om kommentatorer p\xe5peker mangler ved bruk av gjennomsnitt for \xe5 beskrive hele utvalget, og irrelevansen av priser uten tilgang p\xe5 elektrisitet.']}),"\n",(0,i.jsx)(r.h2,{id:"0x0-del-filer-fra-terminalen",children:"0x0: Del filer fra terminalen"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://0x0.st/",children:"Original"}),".\nDen nettbaserte fildelingstjenesten 0x0 er tatt av nettet etter at tysk politi beslagla serverne. Nedleggelsen kom til tross for at 0x0.st hadde et klart forbud mot ulovlig fildeling eller aktivitet. Anonyme opplastinger og eksterne nettadresser ble gjort tilgjengelige ved hjelp av plattformen, som kunne slette filer og sette utl\xf8psdatoer. Tjenestens operat\xf8r, ved navn Mia, sa at hostingkostnadene var 60 euro (65 dollar) i m\xe5neden, samtidig som han la til at tjenesten var blokkert for utgangsnoder p\xe5 grunn av mange regelbrudd, og at opplastere som bryter nettstedets regler, ville f\xe5 IP-adressen sin utestengt. S\xe5 langt er det ikke rapportert om noen arrestasjoner."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35491520",children:"Discussion Service"}),'.\n"Hacker News" omtaler en fildelingstjeneste for terminalen, og deler juridiske risikoer og avskrekkende tiltak. Flere alternativer nevnes. En annen diskusjon om filvertstjenester, foreslo alternativer, men p\xe5pekte manglende st\xf8tte for .rar-filer og opplastinger knyttet til kryptovaluta. CloudFlare-drevet versjon er ogs\xe5 nevnt. En GitHub-side med curl-instruksjoner merket "laget for \xe5 se ut som et krasj" og en kodebit med "forbedringer" med en \xe5pnet applikasjon for YC Summer 2023.']}),"\n",(0,i.jsx)(r.h2,{id:"iran-installerer-kameraer-p\xe5-offentlige-steder-for-\xe5-identifisere-og-straffe-utilsl\xf8rte-kvinner",children:"Iran installerer kameraer p\xe5 offentlige steder for \xe5 identifisere og straffe utilsl\xf8rte kvinner."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.reuters.com/world/middle-east/iran-installs-cameras-public-places-identify-penalise-unveiled-women-police-2023-04-08/",children:"Original"}),".\nIran installerer kameraer p\xe5 offentlige steder for \xe5 identifisere og straffe utilsl\xf8rte kvinner som ikke overholder den obligatoriske kleskoden. Overtredere vil motta tekstmeldinger med advarsler om konsekvensene etter \xe5 ha blitt identifisert. Dette tiltaket er ment \xe5 forhindre motstand mot hijabloven, som har f\xf8rt til at stadig flere iranske kvinner har kastet sl\xf8ret etter at en 22 \xe5r gammel kurdisk kvinne ble drept av sedelighetspolitiet i september i fjor. Myndighetene har oppfordret innbyggerne til \xe5 konfrontere utilsl\xf8rte kvinner, og erkl\xe6ringen vil kreve at bedriftseiere overv\xe5ker overholdelsen av samfunnets normer."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35494941",children:"Discussion Service"}),".\nIran installerer kameraer for \xe5 straffe utilsl\xf8rte kvinner, mens diskusjoner om individuell frihet og religi\xf8s undertrykkelse dukker opp. Discussion Service-brukere debatterer den iranske regjeringens behandling av kvinner og bruken av overv\xe5kningsteknologi, og trekker paralleller til v\xe5penkontrolllover og den potensielle virkningen av AI-drevne kameraer. Brukerne argumenterer for personlige valg og mot tvang, mens noen diskuterer sp\xf8rsm\xe5l knyttet til innvandrersamfunn og kvinners rettigheter. Det er blandede meninger om saken, og det gj\xf8res sammenligninger med nazistiske symboler og taktikker brukt av amerikanske myndigheter for \xe5 dempe uro. Kommentarene reiser viktige sp\xf8rsm\xe5l om overv\xe5king, personvern og kulturelle verdier i utformingen av bruken."]}),"\n",(0,i.jsx)(r.h2,{id:"en-streng-p\xe5-15-gb",children:"En streng p\xe5 1,5 GB"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://blog.backslasher.net/1.5GB-string.html",children:"Original"}),".\nForfatteren beskriver hvordan de i l\xf8pet av sin tidligere rolle oppdaget et betydelig minneavfall i en Java-tjeneste de st\xf8ttet. Ved hjelp av kapasitetsplanleggings\xf8kter var de i stand til \xe5 identifisere minnesl\xf8sende objekter i Java-minnedumpen, inkludert en streng p\xe5 1,5 GB. De fant ut at det skyldtes et designproblem der de lagret mer og mer tilstand til den eksploderte. De delte problemet i en rask l\xf8sning og en langsiktig l\xf8sning, og skrev om stablel\xf8sningen for den langsiktige l\xf8sningen. Forfatteren understreker viktigheten av \xe5 unders\xf8ke detaljene i hvordan programmer bruker ressurser for \xe5 produsere raske gevinster fra starten."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35496712",children:"Discussion Service"}),".\nInnlegget diskuterer optimalisering av minne, eksponentiell vekst og serialiseringsprotokoller, med ulike l\xf8sninger foresl\xe5tt. Brukererfaringer med d\xe5rlige API-er og nettleserfeil deles ogs\xe5. Deretter f\xf8lger en debatt om backslasher.nets domeneregistrering. Ytterligere diskusjoner omfatter tekniske detaljer om effektiv datah\xe5ndtering, komprimering av overf\xf8ringsst\xf8rrelse og omstrukturering av datalagring. Begrensning av strenglengden reiser problemer."]}),"\n",(0,i.jsx)(r.h2,{id:"paul-graham-er-investor-i-selskapet-som-pr\xf8ver-\xe5-drepe-twitter",children:"Paul Graham er investor i selskapet som pr\xf8ver \xe5 drepe Twitter."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://twitter.com/paulg/status/1644635086715858944",children:"Original"}),".\nPaul Grahams investeringsfond, Y Combinator, investerte i en oppstartsbedrift kalt Tilde, som jobber med et desentralisert, \xe5pen kildekode-alternativ til Twitter kalt Mastodon. Mastodons vekst har v\xe6rt jevn, med over 1,2 millioner registrerte brukere, men analytikere mener at det kanskje ikke utgj\xf8r en betydelig trussel mot Twitter p\xe5 grunn av mangelen p\xe5 inntjeningsmuligheter for Mastodon. Noen Discussion Service-brukere kritiserer Graham for \xe5 investere i et selskap som pr\xf8ver \xe5 drepe et annet selskap, mens andre forsvarer prinsippene om konkurranse og innovasjon."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35493046",children:"Discussion Service"}),'.\nPaul Grahams investering i Twitter-drepende selskaper skaper diskusjon om Twitters fremtid. L\xf8nnsomhet og konspirasjonsteoretikere er problemer for Substack som et alternativ. Nisjesamfunn kan ikke erstatte Twitter. Oppdagbarhet og nettverkseffekt er n\xf8kkelen til suksess i sosiale medier. Elon Musks rolle i Twitter er i konflikt med hans ideal om et digitalt offentlig torg. Substack har nettopp lansert "Substack Notes", en Twitter-klone. Stemme- og kontohandel kan skje p\xe5 plattformen. Noen liker Substack, andre sitter p\xe5 gjerdet. Elon Musks suksess med Tesla og SpaceX tilskrives hans lederstil. D\xe5rlig oppf\xf8rsel og sikkerhetsproblemer har f\xf8rt til at noen sverger til \xe5 kj\xf8pe Tesla. Den neste iterasjonen av sosiale medier b\xf8r v\xe6re non-profit med eksplisitte retningslinjer for innhold. Substack utvider seg til mikroblogging, bekymrer Twitter-personligheter. Twitter tiltrekker seg hatefullt innhold og trenger mer regulering. Problemer med roboter har plaget Twitter.']}),"\n",(0,i.jsx)(r.h2,{id:"fcc-advarer-portland-kirke-om-\xe5-stenge-pirat-fm-som-opererer-under-kirket\xe5rnet",children:"FCC advarer Portland kirke om \xe5 stenge pirat FM som opererer under kirket\xe5rnet."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.insideradio.com/free/fcc-warns-portland-church-to-shut-down-pirate-fm-operating-under-its-steeple/article_f89e2ebc-cf96-11ed-9c83-4b0d056dd422.html",children:"Original"}),".\nFederal Communications Commission (FCC) har varslet Eastside Free Methodist Church, basert i Portland, om at en ulisensiert FM-radiostasjon, som opererer p\xe5 90.5 FM, er identifisert for \xe5 operere under kirket\xe5rnet. Feltagenter fra FCC sporet piratradioen, men fant ingen enkeltpersoner der for \xf8yeblikket, og kirken kan v\xe6re stengt i henhold til tilgjengelige online-innlegg. Det er sannsynlig at kirken vil m\xf8te h\xe5ndhevingstiltak i henhold til f\xf8deral lov, ettersom den eier bygningen. Eventuelle bevis b\xf8r fremlegges for \xe5 bevise at piratradiosendingen ikke lenger foreg\xe5r i lokalene. I varselbrevet som er sendt til kirken, st\xe5r det at den vil bli ilagt en bot p\xe5 mer enn 2,3 millioner dollar."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35496871",children:"Discussion Service"}),".\nFCC advarte en kirke i Portland om \xe5 stenge en pirat FM-radiostasjon under kirket\xe5rnet. Slike stasjoner kan forstyrre n\xf8dkommunikasjon, og er ikke en del av EAS. Noen mener imidlertid at piratstasjoner er n\xf8dvendige for uavhengige stemmer. Den p\xe5grepne piraten ble ilagt en bot p\xe5 80 000 dollar og fikk flere advarsler. Diskusjon om regulering, lovlighet og effektivitet av radiobruk og -tildeling fulgte, med forslag om LPFM-stasjoner. Interferens kan for\xe5rsakes av overlapping av analoge og digitale signaler. Noen radioentusiaster i Norge diskuterer FM-piratstasjoner. Reguleringer og kontroll over eteren er et omstridt tema."]}),"\n",(0,i.jsx)(r.h2,{id:"gnulinux-b\xe6rbare-datamaskiner-med-forh\xe5ndsinstallert-libreboot-basert-p\xe5-coreboot",children:"GNU+Linux b\xe6rbare datamaskiner med forh\xe5ndsinstallert Libreboot, basert p\xe5 coreboot."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://minifree.org/",children:"Original"}),".\nMinifree Ltd selger GNU + Linux b\xe6rbare datamaskiner med Libreboot, en BIOS / UEFI-erstatning basert p\xe5 Coreboot, forh\xe5ndsinstallert, med kryptert Debian GNU + Linux OS og full driverst\xf8tte; det tilbyr ogs\xe5 alternativer for andre Linux-distros eller BSD. Den er perfekt for personvernprogramvare som Tor Browser eller Tails, med 480/960 GB SSD, 2x480 GB / 2x960 GB RAID1 SSD, godt batteri og 16 GB RAM. Selskapet tilbyr gratis teknisk st\xf8tte via e-post og IRC, pluss fem \xe5rs garanti, og finansierer utviklingen av Libreboot. Den siste store Libreboot-utgivelsen, versjon 20230319, er n\xe5 tilgjengelig fra Minifree, som installerer den nyeste versjonen som standard."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35496651",children:"Discussion Service"}),".\nMinifree tilbyr GNU+Linux b\xe6rbare datamaskiner med Libreboot forh\xe5ndsinstallert basert p\xe5 coreboot. T440p-modellen gir \xe5pen kildekode BIOS og OS-kontroll, men krever teknisk kunnskap. System76 har bedre maskinvare, men mindre utvalg. Blinkende Coreboot er vanskelig p\xe5 noen maskinvare. Debatt om Intel Management Motors sikkerhetsrisiko. GNUs betydning for Linux-brukere oppveier GNUs sitatfeil. Noen p\xe5peker at systemd ikke er et GNU-prosjekt."]}),"\n",(0,i.jsx)(r.h2,{id:"p\xe5-jakt-etter-regnbuer-design-for-fargeblindhet",children:"P\xe5 jakt etter regnbuer: Design for fargeblindhet"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.theverge.com/23650428/colorblindness-design-ui-accessibility-wordle",children:"Original"}),'.\n"The Verge"-artikkelen diskuterer design for fargeblindhet og retter oppmerksomheten mot det faktum at verden ikke ble designet for mennesker med fargeblindhet. Rundt 350 millioner mennesker p\xe5 verdensbasis er fargeblinde, og rundt 8 % av alle menn har en eller annen form for fargesynssvekkelse. Det gis praktiske eksempler for \xe5 demonstrere vanskelighetene fargeblinde st\xe5r overfor, og artikkelen understreker betydningen av tilgjengelighet i design som en m\xe5te \xe5 vise empati p\xe5.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35489168",children:"Discussion Service"}),".\nDesignere m\xe5 ikke stole p\xe5 farger alene; kontraster og former er avgj\xf8rende for fargeblinde brukere. Bedre design kan im\xf8tekomme fargeblindhet som et aspekt ved universell utforming. Lysstyrke, kontrast, etiketter, ikoner og teksturer bidrar til \xe5 skille farger. Vurder former eller skrifttyper for \xe5 skille mellom elementer. Automatisert tilgjengelighetstesting er tilgjengelig. Fargeblindhet reduserer bare evnen til \xe5 skille mellom fargetoner. Diskusjon om individuell fargeblindhet og oppfatning av trafikklys. Noen frekvenser i gr\xf8nt er vanskelige \xe5 se. Gangskilt ser hvite ut for noen, men gr\xf8nne for andre med fargeblindhet."]}),"\n",(0,i.jsx)(r.h2,{id:"for-\xe5-\xf8ke-l\xe6ringen-se-\xe5-spille",children:"For \xe5 \xf8ke l\xe6ringen, se \xe5 spille"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://nautil.us/to-supercharge-learning-look-to-play-292946/",children:"Original"}),'.\nLek og kunst er avgj\xf8rende for l\xe6ring, og bygger de "6 K-ene": samarbeid, kommunikasjon, innhold, kritisk tenkning, kreativ innovasjon og selvtillit. Playful Learning Landscapes Action Network integrerer lek p\xe5 offentlige steder og fremmer l\xe6ring p\xe5 tvers av generasjoner og mellom jevnaldrende. Oppslukende videospill, utformet med tanke p\xe5 nevroart, kan \xf8ke oppmerksomheten, s\xe6rlig for personer med ADHD. NeuroRacer, et oppslukende videospill designet av Adam Gazzaley, forbedret kognitiv kontroll og oppmerksomhetsevne i kliniske studier for barn med ADHD. N\xe5, kjent som EndeavorRx, er det den f\xf8rste ikke-medikamentelle behandlingen for ADHD, godkjent av FDA i 2020. Adams arbeid legger vekt p\xe5 skj\xe6ringspunktet mellom kunst og vitenskap for \xe5 h\xe5ndtere l\xe6ringsforskjeller.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35494342",children:"Discussion Service"}),".\nEn Discussion Service-bruker antyder at AI-basert l\xe6ring kan lindre stress i utdanning i California, men andre skylder p\xe5 byr\xe5kratisk d\xe5rlig ledelse. AIs innvirkning p\xe5 utdanning debatteres, med bekymringer om sosialisering, disiplin og l\xe6rerveiledning. Lekbetonte l\xe6ringsmetoder, s\xe6rlig for ADHD, diskuteres, og personlige erfaringer deles og ressurser stilles til r\xe5dighet."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-browserbox---gj\xf8r-ting-med-nettlesere-som-du-vanligvis-ikke-kan-gj\xf8re",children:"Vis BrowserBox - gj\xf8r ting med nettlesere som du vanligvis ikke kan gj\xf8re"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/dosyago/BrowserBox",children:"Original"}),".\nBrowserBox er et eksternt, isolert nettleser-API som kan kj\xf8res i skyen eller hostes selv, med en vanlig og en Pro-versjon tilgjengelig. Pro-versjonen har mer avanserte funksjoner, oppdateres ofte og integreres direkte i en nettside, mens den vanlige versjonen har en langsommere utgivelsessyklus. Begge versjonene tilbyr ubegrensede nettleserfunksjoner, mobiltilpasset brukergrensesnitt med flere faner, co-browsing, adaptiv str\xf8mming og sikker dokumentvisning. BB Pro er sv\xe6rt sikker og har en rekke sikkerhetstiltak som RBI-nettleserisolasjonssikkerhetsmodell og innebygd AdBlocker, og programvaren er tilgjengelig under Polyform Shield License 1.0.0."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35490289",children:"Discussion Service"}),".\nBrowserBox f\xe5r oppmerksomhet p\xe5 Hacker News, og gir brukerne tilgang til utilgjengelige filer/koder. L\xf8sninger som tilbys, inkludert localhost-server og nettleserutvidelse. Det stilles sp\xf8rsm\xe5l ved lisenshistorikken, og prisen er et problem. Cloudflares S2 nevnt som alternativ for isolasjon. Dosy Browser gir indirekte gjengivelse av nettsteder ved hjelp av Chrome. Alternative implementeringer foresl\xe5tt. Dosy Browsers lisens for ikke-kommersiell bruk diskutert. Opera Minis enhetsst\xf8tte og datakomprimering minnet om. BrowserBox fungerer som en klient-server-app via automatiseringsprotokoll, noe som gj\xf8r det mulig \xe5 surfe p\xe5 internett p\xe5 eldre tekniske enheter. Prisinformasjon finnes p\xe5 individual.dosyago.com."]}),"\n",(0,i.jsx)(r.h2,{id:"pydantic-v2-omskrevet-i-rust-er-5-50-ganger-raskere-enn-pydantic-v1",children:"Pydantic V2 omskrevet i Rust er 5-50 ganger raskere enn Pydantic V1."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://docs.pydantic.dev/blog/pydantic-v2-alpha/",children:"Original"}),".\nPydantic V2, med en omskrevet pydantic-kjerne, er 5-50 ganger raskere og mer vedlikeholdbar enn Pydantic V1. Biblioteket tilbyr analyse- og valideringsfunksjoner, serialisering, innstillingsadministrasjon og rekursiv datastrukturvalidering, sammen med generering av JSON-skjemaer, egendefinerte typer og feltvalidatorer. Alfaversjonen er \xe5pen for evaluering og eksperimentering i testmilj\xf8er, med tilbakemeldinger for videre utvikling. Pydantic V2 har en AnalyzedType-klasse for enkel validering og serialisering av ikke-BaseModel-objekter, endringer i validering og fjerning av GetterDict. API-et er forel\xf8pig og kan endres."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35490449",children:"Discussion Service"}),".\nPydantic V2 omskrevet i Rust gir en 5-50x ytelses\xf8kning sammenlignet med V1. Rust har utfordringer med forskjellige bin\xe6re plattformer. Drop-in erstatningsbibliotek med mindre API-endringer. Noen brukere kritiserer Pythons mangel p\xe5 optimaliseringsstrategi, mens andre setter pris p\xe5 at det er enkelt for forskere. Python-fellesskapets synkende kodekvalitet er anerkjent. Pydantic V2 roses for funksjoner, men kritiseres for avhengighet av Rust. Noen brukere foresl\xe5r alternativer som msgspec."]}),"\n",(0,i.jsx)(r.h2,{id:"ai-drevne-sanntidsv\xe6skesimuleringer-er-her",children:"AI-drevne sanntidsv\xe6skesimuleringer er her."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://echoesofsomewhere.com/2023/04/06/ai-fluid-simulations/",children:"Original"}),".\nEn utvikler testet et AI-drevet v\xe6skesimuleringsverkt\xf8y for \xe5 legge til realistisk, interaktiv r\xf8yk i et spill, og sammenlignet EmberGen og Zibra Smoke & Fire. Det AI-drevne verkt\xf8yet viste seg \xe5 fungere godt og var mer effektivt enn \xe5 lage v\xe6skeanimasjoner som flip-books. Zibra-verkt\xf8yet er 3D, noe som gj\xf8r at r\xf8yken smelter bedre sammen med omgivelsene og har imponerende ytelse, og kj\xf8rer jevnt p\xe5 en iPhone. Verkt\xf8yet bruker et AI-drevet akselerasjonskonsept og kompakt SDF for representasjon av objektform. Simuleringsgjengivelsen la til ca. 2 ms til bildetider. Verkt\xf8yet har noen kontrollinnstillinger for r\xf8ykens utseende, for eksempel absorpsjon, spredning og skyggefarger."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35490533",children:"Discussion Service"}),".\nV\xe6skesimuleringer i sanntid med AI er 15 ganger raskere enn alternativer, og bruker nevrale nettverk for \xe5 etterligne fysikk. Noen Discussion Service-brukere stiller sp\xf8rsm\xe5l ved bruk av fysikk-informerte nevrale nettverk for v\xe6skedynamikk. AI kan ha potensial for vitenskapelige termodynamiske simuleringer. Uklart hva AI spesifikt gj\xf8r i simuleringen. AI bruker dimensjonsreduksjon p\xe5 grunn av dimensjonalitetsforbannelse. Sannsynligheten for fysisk n\xf8yaktighet i spillsimuleringer er lav. Open source CFD-programvare (OpenFOAM) tilgjengelig, men nettstedet er nede."]}),"\n",(0,i.jsx)(r.h2,{id:"egendefinerte-allokatorer-i-rust",children:"Egendefinerte allokatorer i Rust"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://nical.github.io/posts/rust-custom-allocators.html",children:"Original"}),".\nNicalIndex diskuterer tilpassede allokatorer i Rust for forbedrede minneallokeringsstrategier, slik at forskjellige deler av et program kan velge strategier. Rust har en standard global allokator, med to forslag til st\xf8tte for egendefinert allokator. Artikkelen utforsker tiln\xe6rminger til egendefinerte allokatorer i Rust-datastrukturer, med fokus p\xe5 implementeringen av fill tessellator i lyon-biblioteket. Ulike tiln\xe6rminger involverer levetidsparametere, to strukturer eller et manuelt administrert trekkobjekt. Det er enkelt \xe5 legge til egendefinerte allokatorer og b\xf8r bruke Allocator-egenskapen for best mulig abstraksjon. Resirkulering av tildelinger og valg av riktig tildeler for spesifikke kodedeler er alternativer for utviklere. Allocator-egenskapen m\xe5 stabiliseres for at Storage-implementeringer skal kunne utnytte den."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35491936",children:"Discussion Service"}),'.\nRust kan st\xf8tte dynamisk scoping for egendefinerte allokatorer til tross for den usikre API-utfordringen. Det arbeides med \xe5 kombinere egendefinerte allokatorer med Rusts "std"-typer. "Big box"-problemet i tildeler-API-et krever sikrere h\xe5ndtering av egendefinerte tildelinger i Rust. Overf\xf8ring av containere og levetidskommentarer kan l\xf8se Rusts standardallokeringsproblem. Levetidssystem kan forbedre biblioteksdesign, men ikke optimalisering. En bruker s\xf8ker innspill p\xe5 egendefinerte allokatorer for tensoroperasjoner.']}),"\n",(0,i.jsx)(r.h2,{id:"the-erosion-of-free-will-hvorfor-samfunnets-tap-av-tro-p\xe5-frihet-er-farlig",children:"The Erosion of Free Will: Hvorfor samfunnets tap av tro p\xe5 frihet er farlig"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://read.lukeburgis.com/p/the-erosion-of-free-will-why-societys",children:"Original"}),".\nLuke Burgis hevder at erosjonen av samfunnets tro p\xe5 frihet og fri vilje blir stadig farligere, s\xe6rlig i Silicon Valley, og har etiske konsekvenser for politiske systemer og menneskelig atferd. Burgis foresl\xe5r et nytt rammeverk for \xe5 forst\xe5 frihet, et rammeverk som involverer fysiske, psykologiske og \xe5ndelige aspekter med tolv distinkte momenter. Ved \xe5 oppn\xe5 integritet mener Burgis at fri vilje kan reddes, uten hvilken kj\xe6rlighet i samfunnet ikke kan eksistere."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35489807",children:"Discussion Service"}),".\nEn artikkel p\xe5 Discussion Service diskuterer samfunnets erosjon av troen p\xe5 frihet. Kommentarer utfordrer forfatterens p\xe5stander og kritiserer forenkling av komplekse sp\xf8rsm\xe5l. Begrepet fri vilje er omdiskutert, og noen hevder at det i bunn og grunn ikke eksisterer. Ingen konsensus i j\xf8disk-kristne tradisjoner om betydningen av fri vilje. Noen kommentarer anklager artikkelen for \xe5 ignorere religionenes innflytelse p\xe5 fri vilje. Y Combinator-innlegget gir retningslinjer for Summer 2023-programmet, som henvender seg til oppstartsbedrifter. Verdifull informasjon for teknologikyndige lesere, anbefales \xe5 unng\xe5 kjedelige fakta og opprettholde n\xf8ytralitet."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-l\xe6r-rust-101---en-guide-for-\xe5-hjelpe-deg-med-\xe5-bli-en-rustacean",children:"Vis L\xe6r Rust 101 - En guide for \xe5 hjelpe deg med \xe5 bli en Rustacean"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/plabayo/learn-rust-101/blob/main/README.md",children:"Original"}),'.\nGuiden "learn-rust-101" p\xe5 GitHub er en omfattende ressurs for \xe5 l\xe6re Rust, et popul\xe6rt programmeringsspr\xe5k, med milep\xe6ler for \xe5 l\xe6re ulike konsepter. Andre ressurser inkluderer Rustlings, Programming Rust og boken "Code like a pro in Rust". Leserne oppfordres til \xe5 anvende kunnskapen gjennom valgfrie prosjekter eller ved \xe5 bidra til prosjekter med \xe5pen kildekode. Artikkelen inneholder ogs\xe5 informasjon om bruk av Rust for WebAssembly, egenutviklede apper og webprogrammering, samt ressurser for kontinuerlig l\xe6ring. Deno foresl\xe5s som et sikrere alternativ til NodeJS, og Rust-fellesskapet tilbyr en rekke gratis ressurser.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35489029",children:"Discussion Service"}),'.\nEn guide for \xe5 l\xe6re Rust med fokus p\xe5 generell Rust, ikke bare webutvikling. Rust er et godt valg for produkter som krever backends, 3D-grafikk-API-er og interaksjon med OS-API-er p\xe5 lavt niv\xe5. Rust yter bedre enn Go eller Python p\xe5 GCP skykj\xf8ringer, med lavere minnebruk og rask kj\xf8ring. Tiln\xe6rmingen "l\xe6r ved portering" er en flott m\xe5te \xe5 l\xe6re Rust p\xe5; det er ingen gode gjennomganger for tiln\xe6rmingen for \xf8yeblikket.']}),"\n",(0,i.jsx)(r.h2,{id:"trashcan---nettbasert-tjeneste-for-indeksering-av-vitenskapelige-artikler-eller-andre-dokumenter",children:"Trashcan - nettbasert tjeneste for indeksering av vitenskapelige artikler eller andre dokumenter."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://gitlab.com/mildlyparallel/trashcan",children:"Original"}),".\nIKKE TILGJENGELIG."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492067",children:"Discussion Service"}),".\nEn nettbasert tjeneste for indeksering av vitenskapelige artikler og dokumenter diskuteres med positive vurderinger, og noen nevner sammenlignbare tjenester som I, Librarian og Paperless-ngx, men tjenesten kommer til kort n\xe5r det gjelder automatisk gjenfinning av metadata og oppretting av henvisninger."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-spotify-str\xf8mming-av-gdpr-dump-lokal-analysator",children:"Vis Spotify-str\xf8mming av GDPR-dump lokal analysator"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/pldubouilh/spotify-gdpr-dump-analysis",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35492137",children:"Discussion Service"}),".\nDet er opprettet en ny lokal analysator for GDPR-dumping av Spotify-str\xf8mming, slik at brukerne kan analysere sine egne data. Brukere kan be om eksport av dataene sine og deretter analysere dem ved hjelp av verkt\xf8yet. Mens noen brukere er begeistret for dette, synes andre det er skummelt at Spotify sporer hum\xf8r- og lokasjonsdata. Flere kommentarer p\xe5 tr\xe5den avviker fra hovedpoenget i artikkelen, men det er foresp\xf8rsler om flere verkt\xf8y som dette for \xe5 gi mening om GDPR-dumper."]}),"\n",(0,i.jsx)(r.h2,{id:"hacking-google-recaptcha-v3-ved-hjelp-av-forsterkende-l\xe6ring-2019",children:"Hacking Google ReCAPTCHA v3 ved hjelp av forsterkende l\xe6ring (2019)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://arxiv.org/abs/1903.01003",children:"Original"}),".\nForskere har utviklet en forsterkningsl\xe6ringsmetode for \xe5 omg\xe5 Googles reCAPTCHA v3. Ved \xe5 formulere problemet som en rutenettverden kan agentene l\xe6re \xe5 bevege musen og klikke p\xe5 reCAPTCHA-knappen for \xe5 f\xe5 en h\xf8y poengsum, noe som betyr at metoden bruker en splitt og hersk-strategi for \xe5 beseire dette captcha-systemet for enhver rutenettoppl\xf8sning. Den foresl\xe5tte metoden oppn\xe5r en suksessrate p\xe5 97,4 % p\xe5 et 100x100 rutenett og 96,7 % p\xe5 en skjermoppl\xf8sning p\xe5 1000x1000. Forfatterne viser ogs\xe5 at \xf8kt cellest\xf8rrelse reduserer ytelsen til agenten."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35489342",children:"Discussion Service"}),".\nEn ny artikkel beskriver en Reinforcement Learning-metode for \xe5 omg\xe5 ReCAPTCHA v3. I kommentarene diskuteres mangelen p\xe5 merverdi for dagens systemer og tidligere erfaringer med tilgjengelighetsalternativer. Noen brukere foresl\xe5r alternativer til \xe5 l\xf8se captchas, mens andre stiller sp\xf8rsm\xe5l ved hvordan de vanskeligere captchas er i samsvar med tilgjengelighetsloven. Dokumentet holder kanskje ikke uten validering, og mangelen p\xe5 kritiske detaljer p\xe5pekes."]}),"\n",(0,i.jsx)(r.h2,{id:"eks-brannsjef-med-brudd-i-hodeskallen-etter-angrep-med-metallr\xf8r",children:"Eks-brannsjef med brudd i hodeskallen etter angrep med metallr\xf8r."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.sfchronicle.com/bayarea/article/marina-sf-crime-attack-fire-commissioner-17883532.php",children:"Original"}),".\nTidligere brannkommisjon\xe6r i San Francisco, Don Carmignani, ble innlagt p\xe5 sykehus med kraniebrudd og 51 sting etter \xe5 ha blitt angrepet med en metallgjenstand mens han forlot morens hus i Marina District. Myndighetene har arrestert en mann for det p\xe5st\xe5tte overfallet. Hans venn, Joe Alioto Veronese, hevdet at Carmignani ble sl\xe5tt av tre menn som bodde i et hjeml\xf8st nabolag i n\xe6rheten. Veronese spekulerer i at angrepet kan ha v\xe6rt gjengjeldelse for en telefonsamtale Carmignani ringte tirsdag da han ba politiet om \xe5 fjerne uteliggere foran morens hjem. Hendelsen har vakt bekymring for sikkerheten i byen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35489067",children:"Discussion Service"}),".\nEn tidligere brannkommiss\xe6r i SF ble angrepet, noe som utl\xf8ste diskusjon om SFs kriminalitetsproblem og rettsh\xe5ndhevelse. Brukerne foresl\xe5r strengere rettsh\xe5ndhevelse og allmennvalg. Sosiale tjenester anses som utilstrekkelige, og v\xe5penlover debatteres. Mangel p\xe5 statlig og offentlig sikkerhet og desensitivisering av folk identifiseres som \xe5rsaker og utgangspunkt for endring. Politisk vilje og dogmer er hindringer, og det spekuleres i om fondsbistand indirekte kan skade kriminalitetsbekjempelsen. Samtalen dreier seg om l\xf8sninger p\xe5 SFs problemer, andre grunnlovstillegg og v\xe5penkontroll, og at innbyggerne blir informert om rettigheter og ansvar."]})]})}function k(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);